<template>
  <div class="page-layout article-page is-immersive">
    <main id="main-content" ref="mainRef" class="article-main" @scroll.passive="onScroll">
      <template v-if="!loading && item">
        <button type="button" class="back-link" @click="goBack"><Icon name="ph:arrow-left-bold" /> 返回见闻</button>
        <header class="feed-header article-anim article-ready">
          <div class="feed-kicker"><span class="kicker-dot" :style="{ background: sectionColor }" />{{ sectionLabel }}<i />{{ item.source.name }}</div>
          <h1>{{ item.title }}</h1>
          <div class="feed-meta"><span>{{ item.author || item.source.name }}</span><time :datetime="item.publishedAt">{{ formatDate(item.publishedAt) }}</time><a :href="item.url" target="_blank" rel="noopener noreferrer">查看原文 <Icon name="ph:arrow-up-right-bold" /></a></div>
        </header>
        <div v-if="item.summary" class="feed-excerpt article-anim article-ready"><Icon name="ph:quotes-bold" /><p>{{ item.summary }}</p></div>
        <figure v-if="item.image" class="feed-cover article-anim article-ready"><img :src="item.image" :alt="item.title" /></figure>
        <div ref="contentRef" class="article-shell article-anim article-ready"><ArticleMarkdown :content="item.content || item.summary || '暂无正文内容。'" editor-id="circle-feed-reader" /></div>
        <footer class="feed-footer article-anim article-ready"><span>收录于 {{ sectionLabel }}</span><a :href="item.url" target="_blank" rel="noopener noreferrer">在原站继续阅读 <Icon name="ph:arrow-up-right-bold" /></a></footer>
      </template>
      <section v-else-if="!loading" class="reader-state"><Icon name="ph:file-x-bold" /><h1>文章暂时无法打开</h1><p>这篇内容可能已经从订阅源中移除。</p><button type="button" @click="goBack"><Icon name="ph:arrow-left-bold" /> 返回见闻</button></section>
      <div v-else class="reader-loading"><span /><span /><span /></div>
    </main>
    <ArticleSidebar :editor-id="'circle-feed-reader'" scroll-element="#main-content" :progress="readingProgress" :immersive="true" :catalog-ready="false" :catalog-items="[]" :active-catalog-index="0" />
  </div>
</template>

<script setup lang="ts">
const api = useApi(); const route = useRoute(); const router = useRouter(); const mainRef = ref<HTMLElement | null>(null); const contentRef = ref<HTMLElement | null>(null); const loading = ref(true); const item = ref<any>(null); const readingProgress = ref(0)
const sectionLabel = computed(() => { const explicit = String(item.value?.source?.section || ''); if (explicit === 'thought') return '思考'; if (explicit === 'news') return '新闻'; if (explicit === 'tech') return '科技'; if (explicit === 'ai') return 'AI'; if (explicit === 'friends') return '友链'; const text = `${item.value?.source?.name || ''} ${(item.value?.categories || []).join(' ')}`.toLowerCase(); if (/知乎|新闻|hot|日报|早报/.test(text)) return '新闻'; if (/ai|人工智能|机器学习|openai/.test(text)) return 'AI'; if (/少数派|sspai|科技|tech/.test(text)) return '科技'; if (/mrxwlb|onojyun|mobius|思考|随笔|博客/.test(text)) return '思考'; return '友链' })
const sectionColor = computed(() => ({ 新闻: '#3d7fa9', AI: '#8066aa', 科技: '#2b8b71', 思考: '#b06a45', 友链: '#c18a36' }[sectionLabel.value] || 'var(--c-primary)'))
function formatDate(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date) }
function onScroll() { const host = mainRef.value; const content = contentRef.value; if (!host || !content) return; const max = Math.max(1, content.offsetTop + content.scrollHeight - host.clientHeight); readingProgress.value = Math.min(100, Math.max(0, (host.scrollTop / max) * 100)) }
function goBack() { if (window.history.length > 1) router.back(); else void router.push('/circle') }
const itemId = computed(() => String(route.query.id || route.params.id || ''))
async function load() { loading.value = true; try { item.value = await api.get(`/circle/item/${encodeURIComponent(itemId.value)}`) } catch { item.value = null } finally { loading.value = false; await nextTick(); onScroll() } }
onMounted(load); watch(itemId, load); useHead(() => ({ title: item.value?.title ? `${item.value.title} · 见闻` : '见闻' }))
</script>

<style scoped>
.article-page{--article-inline-pad:clamp(24px,5vw,88px);position:relative;display:flex;min-height:0;overflow:hidden;background:var(--c-bg)}.article-main{position:relative;z-index:1;flex:1;min-width:0;overflow-y:auto;padding:36px var(--article-inline-pad) 72px;scrollbar-gutter:stable}.article-main::-webkit-scrollbar{display:none}.article-main>*{width:min(100%,800px);margin-right:auto;margin-left:auto}.back-link{display:inline-flex;width:auto;align-items:center;gap:6px;margin-bottom:34px;padding:0;border:0;background:transparent;color:var(--c-text-3);cursor:pointer;font:inherit;font-size:.7rem}.back-link:hover{color:var(--c-primary)}.feed-header{padding-bottom:26px;border-bottom:1px solid var(--border)}.feed-kicker{display:flex;align-items:center;gap:8px;color:var(--c-text-2);font:700 .6rem var(--font-mono);letter-spacing:.08em;text-transform:uppercase}.feed-kicker i{width:1px;height:14px;background:var(--border)}.kicker-dot{width:7px;height:7px;border-radius:50%}.feed-header h1{margin:16px 0 0;color:var(--c-text);font:680 clamp(1.9rem,4vw,3.4rem)/1.15 var(--font-system-rounded);letter-spacing:0}.feed-meta{display:flex;flex-wrap:wrap;align-items:center;gap:9px 16px;margin-top:18px;color:var(--c-text-3);font-size:.66rem}.feed-meta a,.feed-footer a{display:inline-flex;align-items:center;gap:5px;color:var(--c-primary);text-decoration:none}.feed-excerpt{display:flex;gap:13px;margin-top:24px;padding:17px 18px;border-left:3px solid var(--c-primary);background:color-mix(in srgb,var(--c-primary-soft) 42%,transparent);color:var(--c-text-2)}.feed-excerpt :deep(svg){flex:0 0 auto;color:var(--c-primary);font-size:1.1rem}.feed-excerpt p{margin:0;font-size:.78rem;line-height:1.85}.feed-cover{margin-top:24px;overflow:hidden;border-radius:8px;background:var(--c-bg-2)}.feed-cover img{display:block;width:100%;max-height:420px;object-fit:cover}.article-shell{padding:26px 0 8px}.feed-footer{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:28px;padding-top:18px;border-top:1px solid var(--border);color:var(--c-text-3);font-size:.64rem}.article-anim{animation:reader-in .62s cubic-bezier(.16,1,.3,1) both}.feed-excerpt.article-anim{animation-delay:.06s}.feed-cover.article-anim{animation-delay:.11s}.article-shell.article-anim{animation-delay:.16s}.feed-footer.article-anim{animation-delay:.21s}.reader-state,.reader-loading{display:grid;min-height:70vh;place-items:center;align-content:center;gap:10px;color:var(--c-text-3);text-align:center}.reader-state :deep(svg){color:var(--c-primary);font-size:2.1rem}.reader-state h1{margin:4px 0 0;color:var(--c-text);font-size:1.15rem}.reader-state p{margin:0;font-size:.7rem}.reader-state button{display:inline-flex;align-items:center;gap:6px;margin-top:7px;padding:8px 12px;border:1px solid var(--border);border-radius:7px;background:transparent;color:var(--c-text-2);cursor:pointer;font:inherit;font-size:.68rem}.reader-loading{display:flex}.reader-loading span{width:7px;height:7px;border-radius:50%;background:var(--c-primary);animation:reader-pulse 1s ease-in-out infinite alternate}.reader-loading span:nth-child(2){animation-delay:.16s}.reader-loading span:nth-child(3){animation-delay:.32s}@keyframes reader-in{from{opacity:0;transform:translateY(14px);filter:blur(2px)}to{opacity:1;transform:none;filter:none}}@keyframes reader-pulse{to{opacity:.25;transform:translateY(-4px)}}
@media(max-width:900px){.article-page :deep(.sidebar-right){display:none}.article-main{padding-top:max(74px,calc(env(safe-area-inset-top) + 58px));padding-right:max(16px,env(safe-area-inset-right));padding-left:max(16px,env(safe-area-inset-left))}}@media(max-width:640px){.back-link{margin-bottom:24px}.feed-header h1{font-size:1.85rem}.feed-meta{gap:7px 11px;font-size:.6rem}.feed-excerpt{margin-top:18px;padding:14px}.feed-cover{margin-top:18px}.article-shell{padding-top:20px}.feed-footer{align-items:flex-start;flex-direction:column;margin-top:22px}}@media(prefers-reduced-motion:reduce){.article-anim,.reader-loading span{animation:none}}
</style>
